<span class="line"><span style="color:#E1E4E8;">         </span><span style="color:#F97583;"> add_header </span><span style="color:#9ECBFF;">&#39;Access-Control-Allow-Origin&#39;</span><span style="color:#E1E4E8;"> $allow_origin;</span></span>
